{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket allows public access",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "HIGH",
      "explanation": "The 'restrict_public_buckets' attribute is set to 'false', which allows public access to the S3 bucket. This can expose sensitive data if the bucket is not properly secured."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket = aws_s3_bucket.api_docs.id\n  restrict_public_buckets = true\n}",
  "fix_summary": "Set 'restrict_public_buckets' to 'true' to prevent public access to the S3 bucket."
}
